/**
 * CartPanda REST API constants.
 *
 * CartPanda exposes its merchant API at:
 *   https://app.cartpanda.com/api/v2/{slug}/
 *
 * The `slug` is the store subdomain — the part before `.cartpanda.com` in
 * the store URL, e.g. `mystore` for `mystore.cartpanda.com`. Authentication
 * uses a long-lived Bearer token generated by the store owner in the
 * CartPanda dashboard (Profile → Token).
 *
 * Docs: https://dev.cartpanda.com/docs/cartx-api-doc
 */
export const API_BASE = 'https://app.cartpanda.com/api/v2'

export const DEFAULT_PAGE_SIZE = 50
export const MAX_PAGE_SIZE = 250
